/**
 * The official wordmark, read from the app's own file at bundle time.
 *
 * `src/assets/logo.svg` is generated by `scripts/generate-wordmark.mjs` and is
 * the one source of the mark. The showreel does not redraw it, does not set it
 * in the font, and does not keep a copy: it imports the file as text (the `?raw`
 * rule in remotion.config.ts) and splits it into the pieces it animates. If the
 * mark is regenerated, the next render picks it up.
 *
 * The file holds two paths. The first is the five letters, one subpath run per
 * letter, letters separated by "Z M" (a counter inside a letter, the hole of the
 * o or the d, follows its outline as "ZM" with no space, so it stays with its
 * letter). The second is the vermillon point.
 */
import source from "../../../src/assets/logo.svg?raw";

type Box = { x0: number; y0: number; x1: number; y1: number; cx: number; cy: number; w: number; h: number };

const boxOf = (d: string): Box => {
  // Every command in the file is absolute (M, L, Q, Z), so the numbers read as
  // plain x,y pairs, control points included. A control point can sit outside
  // the outline, so this box is a slight over-estimate, which is all a pivot needs.
  const n = (d.match(/-?\d+(?:\.\d+)?/g) ?? []).map(Number);
  const xs = n.filter((_, i) => i % 2 === 0);
  const ys = n.filter((_, i) => i % 2 === 1);
  const x0 = Math.min(...xs);
  const x1 = Math.max(...xs);
  const y0 = Math.min(...ys);
  const y1 = Math.max(...ys);
  return { x0, y0, x1, y1, cx: (x0 + x1) / 2, cy: (y0 + y1) / 2, w: x1 - x0, h: y1 - y0 };
};

const paths = [...source.matchAll(/<path d="([^"]+)"/g)].map((m) => m[1]);
const viewBox = (source.match(/viewBox="([^"]+)"/)?.[1] ?? "0 0 1 1").split(/\s+/).map(Number);

if (paths.length !== 2) {
  throw new Error(`src/assets/logo.svg: expected 2 paths (letters, point), found ${paths.length}`);
}

const letters = paths[0].split(/\s+(?=M)/).map((d) => ({ d, box: boxOf(d) }));
if (letters.length !== 5) {
  throw new Error(`src/assets/logo.svg: expected 5 letters, found ${letters.length}`);
}

export const LOGO = {
  viewBox: { x: viewBox[0], y: viewBox[1], w: viewBox[2], h: viewBox[3] },
  letters,
  dot: { d: paths[1], box: boxOf(paths[1]) },
};
